);

create unique index if not exists "uk_vision_stats_daily_scope"
    on "vision_statistics_daily" ("tenant_id", "camera_id", "branch_id", "label", "period_date")
    nulls not distinct;

create index if not exists "idx_vision_stats_daily_tenant_period"
    on "vision_statistics_daily" ("tenant_id", "period_date" desc);

create index if not exists "idx_vision_stats_daily_tenant_camera_period"
    on "vision_statistics_daily" ("tenant_id", "camera_id", "period_date" desc);

create index if not exists "idx_vision_stats_daily_tenant_label_period"
    on "vision_statistics_daily" ("tenant_id", "label", "period_date" desc);

create table if not exists "vision_statistics_monthly" (
    "id" bigint generated by default as identity primary key,
    "tenant_id" bigint not null,
    "camera_id" bigint not null,
    "branch_id" bigint,
    "label" varchar(120) not null,
    "period_month" date not null,
