create unique index if not exists "uk_vision_stats_monthly_scope"
    on "vision_statistics_monthly" ("tenant_id", "camera_id", "branch_id", "label", "period_month")
    nulls not distinct;

create index if not exists "idx_vision_stats_monthly_tenant_period"
    on "vision_statistics_monthly" ("tenant_id", "period_month" desc);

create index if not exists "idx_vision_stats_monthly_tenant_camera_period"
    on "vision_statistics_monthly" ("tenant_id", "camera_id", "period_month" desc);

create index if not exists "idx_vision_stats_monthly_tenant_label_period"
    on "vision_statistics_monthly" ("tenant_id", "label", "period_month" desc);

create table if not exists "vision_alerts" (
    "id" bigint generated by default as identity primary key,
    "tenant_id" bigint not null,
    "camera_id" bigint,
    "branch_id" bigint,
    "label" varchar(120),
    "severity" varchar(30) not null default 'INFO',
    "message" text not null,
    "status" varchar(30) not null default 'OPEN',
    "created_at" timestamp with time zone not null default current_timestamp,
    "resolved_at" timestamp with time zone,
    constraint "fk_vision_alerts_tenant"
        foreign key ("tenant_id") references "erp_tenants" ("id") on delete cascade,
    constraint "fk_vision_alerts_camera"
        foreign key ("camera_id") references "vision_cameras" ("id") on delete set null,
    constraint "fk_vision_alerts_branch"
        foreign key ("branch_id") references "erp_branches" ("id") on delete set null
);

create index if not exists "idx_vision_alerts_tenant_status"
    on "vision_alerts" ("tenant_id", "status", "created_at" desc);

create table if not exists "vision_processing_logs" (
    "id" bigint generated by default as identity primary key,
    "tenant_id" bigint not null,
    "event_id" bigint,
    "camera_id" bigint,
    "level" varchar(20) not null default 'INFO',
    "code" varchar(80),
    "message" text not null,
    "metadata" jsonb not null default '{}'::jsonb,
    "created_at" timestamp with time zone not null default current_timestamp,
    constraint "fk_vision_processing_logs_tenant"
        foreign key ("tenant_id") references "erp_tenants" ("id") on delete cascade,
    constraint "fk_vision_processing_logs_event"
        foreign key ("event_id") references "vision_events" ("id") on delete set null,
    constraint "fk_vision_processing_logs_camera"
        foreign key ("camera_id") references "vision_cameras" ("id") on delete set null
);

create index if not exists "idx_vision_processing_logs_tenant_created"
    on "vision_processing_logs" ("tenant_id", "created_at" desc);

create table if not exists "vision_webhook_logs" (
    "id" bigint generated by default as identity primary key,
    "tenant_id" bigint,
    "provider" varchar(80) not null default 'YOLO',
    "event_id" bigint,
    "idempotency_key" varchar(250),
    "status" varchar(30) not null,
    "request_headers" jsonb not null default '{}'::jsonb,
    "payload_json" jsonb not null default '{}'::jsonb,
    "response_code" varchar(80),
    "response_message" text,
    "created_at" timestamp with time zone not null default current_timestamp,
    constraint "fk_vision_webhook_logs_tenant"
        foreign key ("tenant_id") references "erp_tenants" ("id") on delete set null,
    constraint "fk_vision_webhook_logs_event"
        foreign key ("event_id") references "vision_events" ("id") on delete set null
);

create index if not exists "idx_vision_webhook_logs_tenant_created"
    on "vision_webhook_logs" ("tenant_id", "created_at" desc);

create table if not exists "vision_audit_logs" (
    "id" bigint generated by default as identity primary key,
    "tenant_id" bigint not null,
    "user_id" bigint,
    "action" varchar(100) not null,
    "resource_type" varchar(80) not null,
    "resource_id" bigint,
    "ip_address" varchar(80),
    "metadata" jsonb not null default '{}'::jsonb,
    "created_at" timestamp with time zone not null default current_timestamp,
    constraint "fk_vision_audit_logs_tenant"
        foreign key ("tenant_id") references "erp_tenants" ("id") on delete cascade,
    constraint "fk_vision_audit_logs_user"
        foreign key ("user_id") references "users" ("id") on delete set null
);

create index if not exists "idx_vision_audit_logs_tenant_created"
    on "vision_audit_logs" ("tenant_id", "created_at" desc);

create or replace function "vision_touch_updated_at"()
returns trigger
language plpgsql
as $$
begin
    new."updated_at" = current_timestamp;
    return new;
end;
$$;

drop trigger if exists "trg_vision_api_keys_updated_at" on "vision_api_keys";
create trigger "trg_vision_api_keys_updated_at"
    before update on "vision_api_keys"
    for each row execute function "vision_touch_updated_at"();

drop trigger if exists "trg_vision_cameras_updated_at" on "vision_cameras";
create trigger "trg_vision_cameras_updated_at"
    before update on "vision_cameras"
    for each row execute function "vision_touch_updated_at"();

drop trigger if exists "trg_vision_events_updated_at" on "vision_events";
create trigger "trg_vision_events_updated_at"
    before update on "vision_events"
    for each row execute function "vision_touch_updated_at"();

drop trigger if exists "trg_vision_stats_hourly_updated_at" on "vision_statistics_hourly";
create trigger "trg_vision_stats_hourly_updated_at"
    before update on "vision_statistics_hourly"
    for each row execute function "vision_touch_updated_at"();

drop trigger if exists "trg_vision_stats_daily_updated_at" on "vision_statistics_daily";
create trigger "trg_vision_stats_daily_updated_at"
    before update on "vision_statistics_daily"
    for each row execute function "vision_touch_updated_at"();

drop trigger if exists "trg_vision_stats_monthly_updated_at" on "vision_statistics_monthly";
create trigger "trg_vision_stats_monthly_updated_at"
    before update on "vision_statistics_monthly"
    for each row execute function "vision_touch_updated_at"();
